const $ = id => document.getElementById(id);
const escape = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sample = [
 {id:'RR-104',name:'Maya',repair:'Bicycle brake adjustment',state:'ready',quote:'Saturday from one to three works for me.',windows:['Saturday · 1–3 pm'],turns:[['Assistant','I am an AI assistant for the community workshop. I’m collecting availability; the coordinator will confirm separately. Would Saturday, September 19, from one to three Eastern work?'],['Recipient','Saturday from one to three works for me.']]},
 {id:'RR-105',name:'Theo',repair:'Desk lamp inspection',state:'review',quote:'Friday morning is fine. Actually, wait—I work Friday.',windows:[],turns:[['Assistant','Would Friday morning work for your lamp inspection?'],['Recipient','Friday morning is fine. Actually, wait—I work Friday.'],['Assistant','Is Saturday afternoon possible?'],['Recipient','I need to check. Please call me back.']]},
 {id:'RR-106',name:'Jo',repair:'Sewing machine assessment',state:'ready',quote:'Yes, I can bring it Saturday between one and three.',windows:['Saturday · 1–3 pm'],turns:[['Assistant','This is an AI assistant collecting availability for the workshop. No appointment is booked yet. Can you come Saturday September 19, one to three Eastern?'],['Recipient','Yes, I can bring it Saturday between one and three.']]},
 {id:'RR-107',name:'Alex',repair:'Chair joint repair',state:'review',quote:null,windows:[],turns:[['Assistant','Hello, this is the community workshop assistant.'],['System','Voicemail detected. No availability collected.']]}
];
let cases=structuredClone(sample),selected=cases[0].id,decisions={},capacity=2;
const labels={ready:'Ready to review',review:'Needs follow-up',proposed:'Added to handoff',rejected:'Follow-up requested'};
function notify(message){$('notice').textContent=message;}
function accept(id){const c=cases.find(x=>x.id===id);if(!c||c.state!=='ready')throw Error('Only evidence-supported availability can be proposed.');if(Object.values(decisions).filter(x=>x==='proposed').length>=capacity)throw Error('This session is full. Increase capacity or remove a proposal first.');decisions[id]='proposed';render();notify(`${c.name} added to the coordinator handoff. No appointment has been booked.`);}
function render(){
 $('queue-count').textContent=cases.length;$('capacity-label').textContent=capacity;$('used').textContent=Object.values(decisions).filter(x=>x==='proposed').length;
 $('queue').innerHTML=cases.map(c=>`<button class="case ${selected===c.id?'active':''}" data-id="${escape(c.id)}" aria-current="${selected===c.id}"><strong>${escape(c.name)}</strong><small>${escape(c.repair)}</small><span class="tag ${decisions[c.id]||c.state}">${labels[decisions[c.id]||c.state]}</span></button>`).join('');
 const c=cases.find(x=>x.id===selected),proposed=decisions[c.id]==='proposed';
 $('detail').innerHTML=`<div class="detail-head"><div><p class="eyebrow">${escape(c.id)} / RESPONSE REVIEW</p><h2>${escape(c.repair)}</h2><p>${escape(c.name)} · phone hidden · ${c.id.startsWith('IMPORT-')?'imported locally':'fictional sample'}</p></div><span class="tag ${decisions[c.id]||c.state}">${labels[decisions[c.id]||c.state]}</span></div><blockquote class="quote"><small>Recipient evidence</small>${c.quote?'“'+escape(c.quote)+'”':'No recipient response recorded.'}</blockquote><p class="evidence-note">${c.state==='ready'?'The quote appears in the recipient’s transcript. Read the full exchange before accepting the proposed window.':'There is no supported appointment window. A correction, uncertainty, or unanswered call needs follow-up.'}</p>${c.windows.map(w=>`<div class="window"><strong>${escape(w)}</strong><span>Proposed availability</span></div>`).join('')}<details><summary>Read the full conversation</summary><div class="turns">${c.turns.map(t=>`<p><b>${escape(t[0])}</b><br>${escape(t[1])}</p>`).join('')}</div></details><div class="review-controls"><button id="accept" ${c.state!=='ready'||proposed?'disabled':''}>${proposed?'Added to handoff':'Accept availability'}</button><button id="followup" class="secondary">Needs follow-up</button></div>`;
 document.querySelectorAll('.case').forEach(el=>el.onclick=()=>{selected=el.dataset.id;notify('');render();});
 $('accept').onclick=()=>{try{accept(c.id);}catch(e){notify(e.message);}};
 $('followup').onclick=()=>{decisions[c.id]='rejected';render();notify('Marked for coordinator follow-up. No callback was placed.');};
 const accepted=cases.filter(c=>decisions[c.id]==='proposed');$('accepted').innerHTML=accepted.length?accepted.map(c=>`<div class="handoff-item"><div><strong>${escape(c.name)}</strong><small>${escape(c.repair)} · ${escape(c.windows.join(', '))}</small></div><button class="quiet remove" data-id="${escape(c.id)}" aria-label="Remove ${escape(c.name)}">Remove</button></div>`).join(''):'<p class="empty">No proposals yet. Review a response and accept its availability to build the handoff.</p>';
 document.querySelectorAll('.remove').forEach(el=>el.onclick=()=>{delete decisions[el.dataset.id];render();});
}
$('capacity').onchange=()=>{const v=Number($('capacity').value),used=Object.values(decisions).filter(x=>x==='proposed').length;if(!Number.isInteger(v)||v<Math.max(1,used)||v>20){$('capacity').value=capacity;notify('Capacity must be 1–20 and cannot be lower than existing proposals.');return;}capacity=v;render();notify('Workshop capacity updated.');};
$('reset').onclick=()=>{cases=structuredClone(sample);selected=cases[0].id;decisions={};capacity=2;$('capacity').value=2;render();notify('Sample restored.');};
$('export').onclick=()=>{const packet={synthetic:true,appointment_booked:false,session:'2026-09-19T13:00:00-04:00',capacity,proposals:cases.filter(c=>decisions[c.id]==='proposed').map(c=>({case_id:c.id,repair:c.repair,windows:c.windows,quote:c.quote})),followups:cases.filter(c=>decisions[c.id]==='rejected').map(c=>c.id)};const url=URL.createObjectURL(new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='repair-relay-handoff.json';a.click();URL.revokeObjectURL(url);notify('Handoff exported. Proposals still need coordinator confirmation.');};
$('upload').onchange=async()=>{try{const file=$('upload').files[0];if(!file)return;if(file.size>1000000)throw Error('Use a JSON file smaller than 1 MB.');const result=JSON.parse(await file.text());const r=result?.recipients?.[0],data=r?.structured_result,turns=(r?.attempts||[]).flatMap(a=>a.transcript_turns||[]);if(!r||!data||!Array.isArray(data.available_window_ids))throw Error('Expected a CALL-E response with one recipient and structured_result.');const quoted=typeof data.quote==='string'&&data.quote.trim()&&turns.some(t=>t.speaker==='user'&&typeof t.text==='string'&&t.text.includes(data.quote));const id='IMPORT-'+(cases.length+1);cases.push({id,name:'Imported response',repair:'Review imported call',state:'review',quote:quoted?data.quote:null,windows:[],turns:turns.filter(t=>typeof t.text==='string').map(t=>[t.speaker==='user'?'Recipient':'Assistant',t.text])});selected=id;render();notify('Imported locally. Original case windows are not attached, so this response needs follow-up. No data was uploaded to a server.');}catch(e){notify(e.message);}finally{$('upload').value='';}};
render();
// The same review action is available to supporting browser agents.
if (document.modelContext?.registerTool) {
 const lifecycle = new AbortController();
 const tools = [
  {name:'read_repair_queue',description:'Read the current local repair review queue; does not contact recipients.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return {capacity,appointment_booked:false,cases:cases.map(c=>({id:c.id,state:decisions[c.id]||c.state,windows:c.windows}))};}},
  {name:'stage_repair_availability',description:'Add one evidence-supported response to the local coordinator handoff. Does not book an appointment or place a call.',inputSchema:{type:'object',properties:{case_id:{type:'string'}},required:['case_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.case_id!=='string'||Object.keys(input).some(k=>k!=='case_id'))throw Error('Provide only case_id.');if(decisions[input.case_id]==='proposed')throw Error('Already in the handoff.');accept(input.case_id);return {case_id:input.case_id,state:'proposed',appointment_booked:false};}}
 ];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
